-- PostgreSQL initial schema. AQ-DBMigration baseline must be 0.
-- Apply with AQ-DBMigration; do not edit after this version is deployed.
-- UUIDs and credential hashes are generated by the application.
-- No default administrator or plaintext credentials are seeded here.

CREATE TABLE users (
    id uuid PRIMARY KEY,
    username varchar(100) NOT NULL UNIQUE,
    password_hash text NOT NULL,
    totp_secret_encrypted text,
    totp_enabled boolean NOT NULL DEFAULT false,
    last_totp_step bigint,
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (NOT totp_enabled OR totp_secret_encrypted IS NOT NULL)
);

CREATE TABLE sessions (
    id uuid PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash text NOT NULL UNIQUE,
    scope varchar(20) NOT NULL CHECK (scope IN ('totp_setup', 'authenticated')),
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX sessions_expiry_idx ON sessions(expires_at);

CREATE TABLE recovery_codes (
    id uuid PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    code_hash text NOT NULL UNIQUE,
    used_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE devices (
    id uuid PRIMARY KEY,
    hardware_id varchar(128) NOT NULL UNIQUE,
    name varchar(100) NOT NULL,
    api_key_hash text UNIQUE,
    key_revoked_at timestamptz,
    firmware_version varchar(100),
    modem_version varchar(150),
    last_seen_at timestamptz,
    last_error text,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE sim_cards (
    id uuid PRIMARY KEY,
    iccid varchar(32) NOT NULL UNIQUE,
    name varchar(100) NOT NULL,
    phone_number varchar(32),
    notes text,
    device_id uuid UNIQUE REFERENCES devices(id) ON DELETE SET NULL,
    operator_name varchar(100),
    sim_status varchar(40),
    network_status varchar(40),
    signal_dbm smallint,
    status_sampled_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE pairing_codes (
    id uuid PRIMARY KEY,
    code_hash text NOT NULL UNIQUE,
    created_by uuid NOT NULL REFERENCES users(id),
    expires_at timestamptz NOT NULL,
    consumed_at timestamptz,
    consumed_by uuid REFERENCES devices(id),
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE device_registrations (
    id uuid PRIMARY KEY,
    request_id uuid NOT NULL UNIQUE,
    pairing_code_id uuid NOT NULL UNIQUE REFERENCES pairing_codes(id),
    device_id uuid NOT NULL REFERENCES devices(id),
    sim_id uuid NOT NULL REFERENCES sim_cards(id),
    request_fingerprint text NOT NULL,
    response_encrypted text,
    response_expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE incoming_sms (
    id uuid PRIMARY KEY,
    device_id uuid NOT NULL REFERENCES devices(id),
    sim_id uuid NOT NULL REFERENCES sim_cards(id),
    event_id varchar(128) NOT NULL,
    sender varchar(100),
    body text,
    modem_received_at timestamptz,
    received_at timestamptz NOT NULL DEFAULT now(),
    deleted_at timestamptz,
    UNIQUE (device_id, event_id),
    CHECK (deleted_at IS NOT NULL OR body IS NOT NULL)
);
CREATE INDEX incoming_sms_sim_time_idx ON incoming_sms(sim_id, received_at DESC)
    WHERE deleted_at IS NULL;

CREATE TABLE outgoing_sms (
    id uuid PRIMARY KEY,
    sim_id uuid NOT NULL REFERENCES sim_cards(id),
    created_by uuid NOT NULL REFERENCES users(id),
    idempotency_key varchar(128) NOT NULL,
    request_fingerprint text NOT NULL,
    recipient varchar(32),
    body text,
    status varchar(20) NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'leased', 'sent', 'failed', 'unknown', 'cancelled')),
    retry_of uuid REFERENCES outgoing_sms(id),
    last_error text,
    created_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    deleted_at timestamptz,
    UNIQUE (created_by, idempotency_key),
    CHECK (deleted_at IS NULL OR status IN ('sent', 'failed', 'cancelled')),
    CHECK (deleted_at IS NOT NULL OR (recipient IS NOT NULL AND body IS NOT NULL))
);
CREATE INDEX outgoing_sms_pending_idx ON outgoing_sms(sim_id, created_at)
    WHERE status = 'pending' AND deleted_at IS NULL;
CREATE INDEX outgoing_sms_sim_time_idx ON outgoing_sms(sim_id, created_at DESC)
    WHERE deleted_at IS NULL;

CREATE TABLE send_attempts (
    id uuid PRIMARY KEY,
    outgoing_id uuid NOT NULL REFERENCES outgoing_sms(id),
    device_id uuid NOT NULL REFERENCES devices(id),
    lease_token_hash text NOT NULL UNIQUE,
    phase varchar(20) NOT NULL
        CHECK (phase IN ('claimed', 'submitting', 'sent', 'failed', 'unknown', 'not_sent')),
    claimed_at timestamptz NOT NULL DEFAULT now(),
    lease_expires_at timestamptz NOT NULL,
    reported_at timestamptz,
    modem_reference varchar(100),
    segment_results jsonb NOT NULL DEFAULT '[]'::jsonb,
    error_code varchar(100),
    error_message text
);
CREATE UNIQUE INDEX send_attempts_active_idx ON send_attempts(outgoing_id)
    WHERE phase IN ('claimed', 'submitting', 'unknown');
CREATE INDEX send_attempts_expiry_idx ON send_attempts(lease_expires_at)
    WHERE phase IN ('claimed', 'submitting');

CREATE TABLE notification_channels (
    id uuid PRIMARY KEY,
    name varchar(100) NOT NULL,
    type varchar(20) NOT NULL CHECK (type IN ('smtp', 'bark', 'pushdeer')),
    config jsonb NOT NULL DEFAULT '{}'::jsonb,
    credentials_encrypted text NOT NULL,
    enabled boolean NOT NULL DEFAULT true,
    deleted_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE sim_channel_bindings (
    sim_id uuid NOT NULL REFERENCES sim_cards(id),
    channel_id uuid NOT NULL REFERENCES notification_channels(id),
    PRIMARY KEY (sim_id, channel_id)
);

CREATE TABLE forwarding_jobs (
    id uuid PRIMARY KEY,
    incoming_id uuid NOT NULL REFERENCES incoming_sms(id),
    channel_id uuid NOT NULL REFERENCES notification_channels(id),
    status varchar(20) NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'processing', 'sent', 'failed', 'cancelled')),
    attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    lease_token uuid,
    lease_expires_at timestamptz,
    last_error text,
    completed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (incoming_id, channel_id),
    CHECK (status <> 'processing' OR (lease_token IS NOT NULL AND lease_expires_at IS NOT NULL))
);
CREATE INDEX forwarding_jobs_due_idx ON forwarding_jobs(next_attempt_at)
    WHERE status = 'pending';
CREATE INDEX forwarding_jobs_expiry_idx ON forwarding_jobs(lease_expires_at)
    WHERE status = 'processing';

CREATE TABLE audit_events (
    id uuid PRIMARY KEY,
    user_id uuid REFERENCES users(id),
    device_id uuid REFERENCES devices(id),
    action varchar(100) NOT NULL,
    resource_type varchar(100),
    resource_id uuid,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_events_time_idx ON audit_events(created_at DESC);
